from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]


def read(path: str) -> str:
    return (ROOT / path).read_text(encoding="utf-8")


def write(path: str, content: str) -> None:
    target = ROOT / path
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content, encoding="utf-8", newline="\n")


def replace_once(path: str, old: str, new: str) -> None:
    content = read(path)
    count = content.count(old)
    if count != 1:
        raise RuntimeError(f"Expected exactly one match in {path}, found {count}: {old[:120]!r}")
    write(path, content.replace(old, new, 1))


# Persist LaneCount in domain topology and use it for the legacy textual display too.
replace_once(
    "src/CSharpGit.Domain/History.cs",
    '''public sealed record CommitTopology(int Lane, IReadOnlyList<TopologyEdge> Edges)\n{\n    public int NodeTrackId { get; init; } = Lane;\n    public IReadOnlyList<TopologyEdge> IncomingEdges { get; init; } = [];\n    public bool HasExactGraphTopology { get; init; }\n\n    public string Display => string.Concat(Enumerable.Range(0, Math.Max(Lane + 1, Edges.Select(x => x.ToLane + 1).DefaultIfEmpty(1).Max()))\n        .Select(index => index == Lane ? "● " : "│ "));\n}\n''',
    '''public sealed record CommitTopology(int Lane, IReadOnlyList<TopologyEdge> Edges)\n{\n    public int NodeTrackId { get; init; } = Lane;\n    public int LaneCount { get; init; } = Lane + 1;\n    public IReadOnlyList<TopologyEdge> IncomingEdges { get; init; } = [];\n    public bool HasExactGraphTopology { get; init; }\n\n    public string Display => string.Concat(Enumerable.Range(0, LaneCount)\n        .Select(index => index == Lane ? "● " : "│ "));\n}\n''')

# Build LaneCount in the same topology pass. before.Count covers incoming/from lanes,
# lanes.Count covers outgoing/to lanes, and lane + 1 covers the node itself.
replace_once(
    "src/CSharpGit.Git/GitReferenceHistoryService.cs",
    '''                new CommitTopology(lane, outgoing)\n                {\n                    NodeTrackId = nodeTrackId,\n                    IncomingEdges = incoming,\n                    HasExactGraphTopology = true\n                },\n''',
    '''                new CommitTopology(lane, outgoing)\n                {\n                    NodeTrackId = nodeTrackId,\n                    LaneCount = Math.Max(lane + 1, Math.Max(before.Count, lanes.Count)),\n                    IncomingEdges = incoming,\n                    HasExactGraphTopology = true\n                },\n''')

write(
    "src/CSharpGit.Presentation/Controls/CommitGraph/CommitGraphMetrics.cs",
    '''namespace CSharpGit.Presentation.Controls.CommitGraph;\n\npublic readonly record struct CommitGraphMetrics(\n    double LaneWidth,\n    double HorizontalMargin,\n    double LineThickness,\n    double NodeRadius)\n{\n    public const double DefaultGraphWidth = 120;\n    public const double MaxGraphWidth = 200;\n    public const double DefaultLaneWidth = 16;\n    public const double MinLaneWidth = 8;\n    public const double DefaultHorizontalMargin = 8;\n    public const double DefaultLineThickness = 2;\n    public const double DefaultNodeRadius = 4;\n\n    public static CommitGraphMetrics Default { get; } = new(\n        LaneWidth: DefaultLaneWidth,\n        HorizontalMargin: DefaultHorizontalMargin,\n        LineThickness: DefaultLineThickness,\n        NodeRadius: DefaultNodeRadius);\n\n    public double CalculateWidth(int laneCount)\n    {\n        if (laneCount <= 0)\n        {\n            return 0;\n        }\n\n        return HorizontalMargin * 2\n            + NodeRadius * 2\n            + (laneCount - 1) * LaneWidth;\n    }\n\n    public double GetLaneX(int lane)\n        => HorizontalMargin + NodeRadius + lane * LaneWidth;\n}\n''')

write(
    "src/CSharpGit.Presentation/Controls/CommitGraph/CommitGraphLayoutState.cs",
    '''namespace CSharpGit.Presentation.Controls.CommitGraph;\n\npublic sealed class CommitGraphLayoutState\n{\n    public int ObservedMaxLaneCount { get; private set; }\n    public double GraphWidth { get; private set; } = CommitGraphMetrics.DefaultGraphWidth;\n    public double LaneWidth { get; private set; } = CommitGraphMetrics.DefaultLaneWidth;\n    public CommitGraphMetrics Metrics => CommitGraphMetrics.Default with { LaneWidth = LaneWidth };\n\n    public bool ObserveLaneCount(int laneCount)\n    {\n        if (laneCount <= ObservedMaxLaneCount)\n        {\n            return false;\n        }\n\n        ObservedMaxLaneCount = laneCount;\n        var previousWidth = GraphWidth;\n        var previousLaneWidth = LaneWidth;\n        Recalculate();\n        return !AreEqual(previousWidth, GraphWidth) || !AreEqual(previousLaneWidth, LaneWidth);\n    }\n\n    public bool Reset()\n    {\n        var changed = ObservedMaxLaneCount != 0\n            || !AreEqual(GraphWidth, CommitGraphMetrics.DefaultGraphWidth)\n            || !AreEqual(LaneWidth, CommitGraphMetrics.DefaultLaneWidth);\n\n        ObservedMaxLaneCount = 0;\n        GraphWidth = CommitGraphMetrics.DefaultGraphWidth;\n        LaneWidth = CommitGraphMetrics.DefaultLaneWidth;\n        return changed;\n    }\n\n    private void Recalculate()\n    {\n        if (ObservedMaxLaneCount <= 0)\n        {\n            GraphWidth = CommitGraphMetrics.DefaultGraphWidth;\n            LaneWidth = CommitGraphMetrics.DefaultLaneWidth;\n            return;\n        }\n\n        var defaultMetrics = CommitGraphMetrics.Default;\n        var requiredWidth = defaultMetrics.CalculateWidth(ObservedMaxLaneCount);\n        if (requiredWidth <= CommitGraphMetrics.DefaultGraphWidth)\n        {\n            GraphWidth = CommitGraphMetrics.DefaultGraphWidth;\n            LaneWidth = CommitGraphMetrics.DefaultLaneWidth;\n            return;\n        }\n\n        if (requiredWidth <= CommitGraphMetrics.MaxGraphWidth)\n        {\n            GraphWidth = requiredWidth;\n            LaneWidth = CommitGraphMetrics.DefaultLaneWidth;\n            return;\n        }\n\n        GraphWidth = CommitGraphMetrics.MaxGraphWidth;\n        var laneDivisor = Math.Max(1, ObservedMaxLaneCount - 1);\n        var availableLaneSpace = CommitGraphMetrics.MaxGraphWidth\n            - defaultMetrics.HorizontalMargin * 2\n            - defaultMetrics.NodeRadius * 2;\n        LaneWidth = Math.Clamp(\n            availableLaneSpace / laneDivisor,\n            CommitGraphMetrics.MinLaneWidth,\n            CommitGraphMetrics.DefaultLaneWidth);\n    }\n\n    private static bool AreEqual(double left, double right)\n        => Math.Abs(left - right) <= 0.0001;\n}\n''')

write(
    "src/CSharpGit.Presentation/Controls/CommitTopologyToGraphVisualConverter.cs",
    '''using CSharpGit.Domain;\nusing CSharpGit.Presentation.Controls.CommitGraph;\nusing Microsoft.UI.Xaml.Data;\n\nnamespace CSharpGit.Presentation.Controls;\n\npublic sealed class CommitTopologyToGraphVisualConverter : IValueConverter\n{\n    public object? Convert(object value, Type targetType, object parameter, string language)\n    {\n        if (value is not CommitTopology topology)\n        {\n            return null;\n        }\n\n        var exactTopology = topology.HasExactGraphTopology;\n        var laneCount = topology.LaneCount;\n\n        var incoming = exactTopology\n            ? topology.IncomingEdges.Select(ToSegment).ToList()\n            : Enumerable.Range(0, laneCount)\n                .Select(lane => new CommitGraphSegment(lane, lane, lane))\n                .ToList();\n\n        var outgoing = exactTopology\n            ? topology.Edges.Select(ToSegment).ToList()\n            : Enumerable.Range(0, laneCount)\n                .Where(lane => lane != topology.Lane)\n                .Select(lane => new CommitGraphSegment(lane, lane, lane))\n                .Concat(topology.Edges.Select(edge => new CommitGraphSegment(edge.FromLane, edge.ToLane, edge.FromLane)))\n                .ToList();\n\n        return new CommitGraphRowVisual(\n            topology.Lane,\n            exactTopology ? topology.NodeTrackId : topology.Lane,\n            laneCount,\n            incoming,\n            outgoing);\n    }\n\n    public object ConvertBack(object value, Type targetType, object parameter, string language) =>\n        throw new NotSupportedException();\n\n    private static CommitGraphSegment ToSegment(TopologyEdge edge) =>\n        new(edge.FromLane, edge.ToLane, edge.TrackId);\n}\n''')

write(
    "src/CSharpGit.Presentation/Controls/CommitGraph/CommitGraphControl.cs",
    '''using CSharpGit.Presentation.Controls.CommitGraph;\nusing Microsoft.UI;\nusing Microsoft.UI.Xaml;\nusing Microsoft.UI.Xaml.Controls;\nusing Microsoft.UI.Xaml.Media;\nusing Windows.Foundation;\nusing XamlPath = Microsoft.UI.Xaml.Shapes.Path;\n\nnamespace CSharpGit.Presentation.Controls;\n\npublic sealed class CommitGraphControl : Canvas\n{\n    private static readonly SolidColorBrush[] LightPalette =\n    [\n        Brush(0x00, 0x5A, 0x9E),\n        Brush(0xC2, 0x39, 0x74),\n        Brush(0x10, 0x7C, 0x10),\n        Brush(0xCA, 0x50, 0x10),\n        Brush(0x74, 0x4D, 0xA9),\n        Brush(0x03, 0x83, 0x87),\n        Brush(0xA4, 0x26, 0x2C),\n        Brush(0x6B, 0x69, 0x00),\n    ];\n\n    private static readonly SolidColorBrush[] DarkPalette =\n    [\n        Brush(0x60, 0xCD, 0xFF),\n        Brush(0xFF, 0x99, 0xA4),\n        Brush(0x6C, 0xCB, 0x5F),\n        Brush(0xFF, 0xB9, 0x00),\n        Brush(0xB4, 0xA0, 0xFF),\n        Brush(0x4C, 0xE4, 0xE4),\n        Brush(0xFF, 0x8A, 0x80),\n        Brush(0xD7, 0xD0, 0x6B),\n    ];\n\n    private readonly XamlPath[] _trackPaths = new XamlPath[8];\n    private readonly XamlPath _nodePath;\n    private readonly RectangleGeometry _clipGeometry = new();\n    private CommitGraphRowVisual? _renderedGraph;\n    private CommitGraphMetrics _metrics = CommitGraphMetrics.Default;\n    private CommitGraphMetrics _renderedMetrics;\n    private double _renderedHeight;\n    private ElementTheme? _renderedTheme;\n    private long _renderCount;\n\n    public static readonly DependencyProperty GraphProperty = DependencyProperty.Register(\n        nameof(Graph),\n        typeof(CommitGraphRowVisual),\n        typeof(CommitGraphControl),\n        new PropertyMetadata(null, OnGraphChanged));\n\n    public CommitGraphRowVisual? Graph\n    {\n        get => (CommitGraphRowVisual?)GetValue(GraphProperty);\n        set => SetValue(GraphProperty, value);\n    }\n\n    public CommitGraphMetrics Metrics\n    {\n        get => _metrics;\n        set\n        {\n            if (_metrics == value)\n            {\n                return;\n            }\n\n            _metrics = value;\n            foreach (var path in _trackPaths)\n                path.StrokeThickness = value.LineThickness;\n            InvalidateMeasure();\n            UpdateGeometry();\n        }\n    }\n\n    public CommitGraphControl()\n    {\n        IsHitTestVisible = false;\n        Clip = _clipGeometry;\n\n        for (var paletteIndex = 0; paletteIndex < _trackPaths.Length; paletteIndex++)\n        {\n            var path = new XamlPath\n            {\n                StrokeThickness = Metrics.LineThickness,\n                IsHitTestVisible = false,\n            };\n            _trackPaths[paletteIndex] = path;\n            Children.Add(path);\n        }\n\n        _nodePath = new XamlPath { IsHitTestVisible = false };\n        Children.Add(_nodePath);\n        UpdateBrushes();\n\n        Loaded += (_, _) =>\n        {\n            UpdateClip();\n            UpdateGeometry();\n        };\n        DataContextChanged += (_, _) => UpdateGeometry();\n        SizeChanged += (_, _) =>\n        {\n            UpdateClip();\n            UpdateGeometry();\n        };\n        ActualThemeChanged += (_, _) =>\n        {\n            UpdateBrushes();\n            UpdateGeometry();\n        };\n    }\n\n    protected override Size MeasureOverride(Size availableSize)\n    {\n        var measured = base.MeasureOverride(availableSize);\n        var width = double.IsFinite(availableSize.Width) ? Math.Max(0, availableSize.Width) : 0;\n        return new Size(width, measured.Height);\n    }\n\n    private static void OnGraphChanged(DependencyObject dependencyObject, DependencyPropertyChangedEventArgs args)\n    {\n        if (dependencyObject is not CommitGraphControl control)\n        {\n            return;\n        }\n\n        control.InvalidateMeasure();\n        control.UpdateGeometry();\n    }\n\n    private void UpdateClip()\n    {\n        var width = double.IsFinite(ActualWidth) && ActualWidth > 0 ? ActualWidth : 0;\n        var height = double.IsFinite(ActualHeight) && ActualHeight > 0 ? ActualHeight : 0;\n        _clipGeometry.Rect = new Rect(0, 0, width, height);\n    }\n\n    private void UpdateGeometry()\n    {\n        var graph = Graph;\n        var height = ActualHeight;\n        if (!double.IsFinite(height) || height <= 0)\n        {\n            return;\n        }\n\n        var metrics = Metrics;\n        var theme = ActualTheme;\n\n        if (ReferenceEquals(_renderedGraph, graph)\n            && Math.Abs(_renderedHeight - height) <= 0.01\n            && _renderedTheme == theme\n            && _renderedMetrics == metrics)\n        {\n            return;\n        }\n\n        foreach (var path in _trackPaths)\n            path.Data = null;\n        _nodePath.Data = null;\n        _nodePath.Fill = null;\n\n        _renderedGraph = graph;\n        _renderedHeight = height;\n        _renderedTheme = theme;\n        _renderedMetrics = metrics;\n        Interlocked.Increment(ref _renderCount);\n\n        if (graph is null)\n        {\n            return;\n        }\n\n        var geometry = CommitGraphGeometryBuilder.Build(graph, height, metrics);\n        var pathGeometries = Enumerable.Range(0, _trackPaths.Length)\n            .Select(_ => new PathGeometry())\n            .ToArray();\n\n        foreach (var bezier in geometry.Beziers)\n        {\n            var figure = new PathFigure\n            {\n                StartPoint = ToPoint(bezier.Start),\n                IsClosed = false,\n                IsFilled = false,\n            };\n            figure.Segments.Add(new BezierSegment\n            {\n                Point1 = ToPoint(bezier.Control1),\n                Point2 = ToPoint(bezier.Control2),\n                Point3 = ToPoint(bezier.End),\n            });\n            pathGeometries[PaletteIndex(bezier.TrackId)].Figures.Add(figure);\n        }\n\n        foreach (var line in geometry.Lines)\n        {\n            var figure = new PathFigure\n            {\n                StartPoint = ToPoint(line.Start),\n                IsClosed = false,\n                IsFilled = false,\n            };\n            figure.Segments.Add(new LineSegment { Point = ToPoint(line.End) });\n            pathGeometries[PaletteIndex(line.TrackId)].Figures.Add(figure);\n        }\n\n        for (var paletteIndex = 0; paletteIndex < _trackPaths.Length; paletteIndex++)\n        {\n            if (pathGeometries[paletteIndex].Figures.Count > 0)\n                _trackPaths[paletteIndex].Data = pathGeometries[paletteIndex];\n        }\n\n        if (geometry.Node is { } node)\n        {\n            _nodePath.Data = new EllipseGeometry\n            {\n                Center = ToPoint(node.Center),\n                RadiusX = node.Radius,\n                RadiusY = node.Radius,\n            };\n            _nodePath.Fill = GetTrackBrush(node.TrackId);\n        }\n    }\n\n    internal bool HasCurrentRenderForCheck()\n    {\n        var height = ActualHeight;\n        if (!double.IsFinite(height) || height <= 0\n            || !ReferenceEquals(_renderedGraph, Graph)\n            || _renderedTheme != ActualTheme\n            || _renderedMetrics != Metrics\n            || Volatile.Read(ref _renderCount) == 0\n            || Math.Abs(_renderedHeight - height) > 0.01)\n        {\n            return false;\n        }\n\n        if (Graph is null)\n        {\n            return _trackPaths.All(path => path.Data is null) && _nodePath.Data is null;\n        }\n\n        var geometry = CommitGraphGeometryBuilder.Build(Graph, height, Metrics);\n        var expectedPaletteIndexes = geometry.Lines.Select(line => PaletteIndex(line.TrackId))\n            .Concat(geometry.Beziers.Select(bezier => PaletteIndex(bezier.TrackId)))\n            .ToHashSet();\n\n        for (var paletteIndex = 0; paletteIndex < _trackPaths.Length; paletteIndex++)\n        {\n            if ((_trackPaths[paletteIndex].Data is not null) != expectedPaletteIndexes.Contains(paletteIndex))\n                return false;\n        }\n\n        return (_nodePath.Data is not null) == (geometry.Node is not null);\n    }\n\n    internal bool HasCurrentClipForCheck()\n    {\n        var expectedWidth = double.IsFinite(ActualWidth) && ActualWidth > 0 ? ActualWidth : 0;\n        var expectedHeight = double.IsFinite(ActualHeight) && ActualHeight > 0 ? ActualHeight : 0;\n        var clip = _clipGeometry.Rect;\n        return Math.Abs(clip.X) <= 0.01\n            && Math.Abs(clip.Y) <= 0.01\n            && Math.Abs(clip.Width - expectedWidth) <= 0.01\n            && Math.Abs(clip.Height - expectedHeight) <= 0.01;\n    }\n\n    private void UpdateBrushes()\n    {\n        var palette = ActualTheme == ElementTheme.Dark ? DarkPalette : LightPalette;\n        for (var paletteIndex = 0; paletteIndex < _trackPaths.Length; paletteIndex++)\n            _trackPaths[paletteIndex].Stroke = palette[paletteIndex];\n    }\n\n    private SolidColorBrush GetTrackBrush(int trackId)\n    {\n        var palette = ActualTheme == ElementTheme.Dark ? DarkPalette : LightPalette;\n        return palette[PaletteIndex(trackId)];\n    }\n\n    private static int PaletteIndex(int trackId)\n        => CommitGraphGeometryBuilder.GetPaletteIndex(trackId, LightPalette.Length);\n\n    private static Point ToPoint(GraphPoint point) => new(point.X, point.Y);\n\n    private static SolidColorBrush Brush(byte red, byte green, byte blue)\n        => new(ColorHelper.FromArgb(0xFF, red, green, blue));\n}\n''')

